mapper.update:
UPDATE ARTICLE SET STATUS = -1
WHERE ARTICLE_CODE = #{articleCode}
  AND WRITER_CODE = #{writerCode}

UPDATE ARTICLE
SET TITLE = #{title},
    CONTENT = #{content}
WHERE ARTICLE_CODE = #{articleCode}
  AND WRITER_CODE = #{writerCode}
  AND STATUS = 1

UPDATE ARTICLE
SET VIEWS = VIEWS+1
WHERE ARTICLE_CODE = #{articleCode}
  AND WRITER_CODE != #{writerCode}
  AND STATUS = 1

UPDATE "COMMENT"
SET STATUS = -1
WHERE COMMENT_CODE = #{commentCode}
  AND WRITER_CODE = #{writerCode}
